INSERT OR IGNORE INTO courses (id,slug,title,description,status,published_at,created_at,updated_at) VALUES ('career-course-job-safety','seguranca-na-busca-de-emprego','Segurança na busca de emprego','Aprenda a conferir anúncios, proteger seus dados e reagir com calma a contatos suspeitos durante a busca por trabalho.','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
INSERT OR IGNORE INTO course_versions (id,course_id,version,status,pass_score,created_at,published_at) VALUES ('career-course-job-safety-v1','career-course-job-safety',1,'published',70,'2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('career-course-job-safety-v1-m0','career-course-job-safety-v1','Procure oportunidades com mais segurança',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-job-safety-v1-m0-l0','career-course-job-safety-v1-m0','Confira a origem do anúncio','[{"title":"Observe antes de responder","text":"Um anúncio pode chegar por site, rede social, grupo ou mensagem direta. Antes de enviar qualquer informação, procure o nome da organização, a função, as tarefas e um canal oficial de contato. Um logotipo ou nome conhecido, sozinho, não prova quem publicou.\n\nCompare o endereço do site e o e-mail com os canais públicos da organização. Diferenças pequenas na escrita, páginas recém-criadas e contatos que evitam explicar a vaga merecem uma verificação adicional."},{"title":"Procure coerência na oportunidade","text":"Leia se as tarefas, os requisitos, o local e as etapas do processo combinam entre si. Promessas de contratação garantida, remuneração muito acima do contexto sem explicação ou urgência extrema podem ser usadas para impedir que você confira os fatos.\n\nUma vaga legítima também pode ter uma descrição ruim, por isso um sinal isolado não fecha o diagnóstico. Reúna os sinais e peça informações pelo canal oficial antes de continuar."},{"title":"Confirme por um caminho independente","text":"Não use apenas o telefone ou link enviado na própria mensagem. Procure o site oficial por conta própria e veja se a oportunidade ou o contato aparecem ali. Quando houver dúvida, use um canal público da organização para confirmar o processo.\n\nPrática: diante de um anúncio fictício, anote três elementos que você verificaria: endereço completo da página, existência da vaga no canal oficial e coerência entre tarefas e condições."}]',8,0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-safety-v1-m0-l0-q0','career-course-job-safety-v1-m0-l0','single_choice','Você recebeu uma vaga por mensagem com um link parecido com o site de uma empresa conhecida. Qual é o primeiro passo mais seguro?','Buscar o canal oficial de forma independente reduz o risco de confiar em um endereço imitado. O logotipo e a urgência da mensagem não confirmam a origem.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l0-q0-o0','career-course-job-safety-v1-m0-l0-q0','Abrir o link imediatamente porque o logotipo parece correto',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l0-q0-o1','career-course-job-safety-v1-m0-l0-q0','Procurar o site oficial por conta própria e confirmar a oportunidade',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l0-q0-o2','career-course-job-safety-v1-m0-l0-q0','Encaminhar a mensagem para todos os contatos antes de verificar',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-safety-v1-m0-l0-q1','career-course-job-safety-v1-m0-l0','reflection','Liste três verificações que você faria antes de responder a um anúncio fictício. Não inclua links ou contatos reais.','Uma boa lista considera a origem, a coerência da descrição e um canal independente de confirmação. Ela deve poder ser aplicada antes de compartilhar dados.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-job-safety-v1-m0-l1','career-course-job-safety-v1-m0','Proteja seus dados e seu dinheiro','[{"title":"Compartilhe somente o necessário","text":"Em uma candidatura inicial, normalmente bastam informações profissionais e um meio de contato. Senhas, códigos de confirmação, dados bancários e números completos de documentos não demonstram sua capacidade para uma vaga.\n\nAntes de preencher um formulário, confira quem receberá os dados, para qual finalidade e se aquele momento do processo realmente exige a informação. Quando a solicitação parecer excessiva, interrompa e confirme pelo canal oficial."},{"title":"Desconfie de pagamentos antecipados","text":"Cobranças para liberar uma entrevista, garantir contratação ou receber salário são sinais importantes de risco. Também tenha cuidado com pedidos para comprar materiais de um fornecedor indicado, movimentar dinheiro de terceiros ou emprestar sua conta.\n\nCursos opcionais podem existir fora de um processo seletivo, mas a decisão de estudar deve ser separada da promessa de vaga. Não faça pagamento sob pressão e converse com alguém de confiança quando a situação estiver confusa."},{"title":"Cuide de arquivos e códigos","text":"Revise o currículo antes de enviar e retire números de documentos, endereço completo e outras informações que não sejam necessárias. Não instale programas desconhecidos nem permita acesso remoto ao aparelho para participar de uma seleção.\n\nCódigos enviados por SMS ou aplicativo servem para confirmar seu acesso e não devem ser repassados. Prática: revise uma lista fictícia e separe dados profissionais adequados de senhas, códigos e informações financeiras."}]',8,1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-safety-v1-m0-l1-q0','career-course-job-safety-v1-m0-l1','multiple_choice','Quais solicitações devem fazer você interromper o contato e verificar a situação? Selecione todas as adequadas.','Pagamento para garantir vaga, senha e código de acesso não são necessários para avaliar qualificações. Informar uma experiência real no currículo faz parte da candidatura.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l1-q0-o0','career-course-job-safety-v1-m0-l1-q0','Pagar uma taxa para garantir a contratação',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l1-q0-o1','career-course-job-safety-v1-m0-l1-q0','Enviar um código de confirmação recebido no celular',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l1-q0-o2','career-course-job-safety-v1-m0-l1-q0','Descrever uma experiência real relacionada à vaga',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l1-q0-o3','career-course-job-safety-v1-m0-l1-q0','Informar a senha do e-mail para validar o cadastro',1,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-safety-v1-m0-l1-q1','career-course-job-safety-v1-m0-l1','reflection','Escreva quais informações profissionais você aceitaria compartilhar no início de uma candidatura fictícia e quais recusaria.','A resposta deve separar informações profissionais necessárias de senhas, códigos, dados financeiros e documentos completos. Em caso de dúvida, confirme antes de enviar.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-job-safety-v1-m0-l2','career-course-job-safety-v1-m0','Interrompa e registre uma situação suspeita','[{"title":"Pare antes de decidir sob pressão","text":"Mensagens suspeitas costumam criar medo de perder a oportunidade. Você pode interromper a conversa, fechar a página e verificar com calma. Não é necessário discutir com o contato nem explicar todos os motivos da sua decisão.\n\nSe já informou algo, evite enviar novos dados para tentar corrigir a situação. Identifique o que foi compartilhado e procure os canais adequados para proteger a conta ou informação envolvida."},{"title":"Guarde informações sem se expor mais","text":"Registre a data, o canal, o nome usado no anúncio e capturas das mensagens relevantes, sem redistribuir dados pessoais de outras pessoas. Esses elementos ajudam a relatar o caso para a plataforma, organização envolvida ou serviço apropriado.\n\nNão clique novamente em links suspeitos apenas para produzir uma captura. Use o que já está disponível e preserve sua segurança. Bloquear um contato pode ser adequado depois de registrar o necessário."},{"title":"Procure ajuda adequada","text":"Se uma conta ou senha foi exposta, altere a credencial pelo site oficial e encerre sessões desconhecidas. Se houve movimentação financeira, procure imediatamente a instituição pelos canais oficiais. Para ameaças ou possíveis crimes, considere os serviços públicos competentes da sua região.\n\nEste curso oferece prevenção geral, não investigação nem orientação jurídica. Prática: escreva um plano fictício com três passos — interromper, registrar e buscar o canal adequado."}]',8,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-safety-v1-m0-l2-q0','career-course-job-safety-v1-m0-l2','single_choice','Você percebeu sinais de fraude depois de enviar uma senha. Qual atitude é mais adequada?','Interromper o contato e alterar a senha pelo serviço oficial reduz novos riscos. Continuar a conversa ou enviar outro código pode ampliar a exposição.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l2-q0-o0','career-course-job-safety-v1-m0-l2-q0','Continuar conversando até a pessoa prometer apagar a senha',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l2-q0-o1','career-course-job-safety-v1-m0-l2-q0','Interromper o contato e alterar a senha pelo canal oficial',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-job-safety-v1-m0-l2-q0-o2','career-course-job-safety-v1-m0-l2-q0','Enviar também o código recebido para confirmar sua identidade',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-job-safety-v1-m0-l2-q1','career-course-job-safety-v1-m0-l2','reflection','Monte um plano fictício em três passos para reagir a um contato suspeito, sem citar pessoas, empresas ou dados reais.','O plano deve começar pela interrupção do contato, preservar apenas evidências seguras e indicar um canal oficial ou serviço adequado para pedir ajuda.',1);
