INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-digital-skills-v1-m0-l0','career-course-digital-skills-v1-m0','Organize e envie arquivos','[{"title":"Crie nomes que ajudam a encontrar","text":"Um nome de arquivo deve explicar o conteúdo sem precisar abri-lo. Prefira uma estrutura como tipo, assunto e data: `curriculo-nome-2026.pdf` ou `lista-materiais-2026-09.xlsx`. Evite nomes como `final-final-agora` e caracteres que podem causar problemas em outros sistemas.\n\nCrie pastas por assunto e mantenha uma versão principal. Se precisar preservar uma etapa anterior, inclua a data ou um número de versão claro."},{"title":"Escolha o formato certo","text":"Use PDF quando quiser preservar a aparência e não esperar edição. Use um formato editável quando a outra pessoa precisar continuar o trabalho. Antes de enviar, abra o arquivo final e confira páginas, conteúdo, nome e tamanho.\n\nNão mude apenas a extensão do nome para converter um arquivo. Use a opção de exportar ou salvar no formato desejado e mantenha o original quando ele puder ser útil."},{"title":"Envie com contexto","text":"Na mensagem, informe o que está anexado, a qual tarefa se refere e se existe algum prazo ou ação esperada. Confira destinatário e anexo antes de enviar. Para arquivos compartilhados por link, revise quem possui acesso.\n\nPrática: crie um nome fictício para uma lista de materiais e escreva uma mensagem curta que explique o anexo e o próximo passo, sem usar contatos reais."}]',8,0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-digital-skills-v1-m0-l0-q0','career-course-digital-skills-v1-m0-l0','single_choice','Você precisa enviar um documento pronto para leitura, sem edição. Qual opção ajuda mais?','Um nome descritivo e a exportação para PDF ajudam a identificar o arquivo e preservar sua aparência. Ainda é necessário abrir e conferir o resultado.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l0-q0-o0','career-course-digital-skills-v1-m0-l0-q0','Renomear qualquer arquivo para final.pdf sem converter',0,0);
