INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l0-q0-o2','career-course-digital-skills-v1-m0-l0-q0','Enviar o primeiro arquivo da pasta sem abrir',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-digital-skills-v1-m0-l0-q1','career-course-digital-skills-v1-m0-l0','reflection','Crie um nome claro para um arquivo fictício e uma mensagem curta de envio com contexto e próximo passo.','O nome deve indicar o conteúdo e a mensagem deve permitir que o destinatário entenda por que recebeu o arquivo e o que precisa fazer.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-digital-skills-v1-m0-l1','career-course-digital-skills-v1-m0','Participe de reuniões online','[{"title":"Prepare o acesso","text":"Confira horário, fuso, aplicativo e link antes da reunião. Quando possível, teste câmera, microfone e saída de áudio. Tenha uma alternativa, como telefone ou mensagem para avisar caso a conexão falhe.\n\nEntre alguns minutos antes sem divulgar o link em canais públicos. Links de reunião podem dar acesso a conversas e informações da equipe, por isso devem ser tratados como acesso de trabalho."},{"title":"Ajude a conversa a funcionar","text":"Mantenha o microfone fechado quando houver ruído e abra para falar. Use o chat ou a função de levantar a mão conforme o combinado do grupo. Diga seu nome quando necessário e avise de forma breve se perder parte da explicação.\n\nEscolha um ambiente possível, sem exigir perfeição. Fones podem ajudar, mas não são obrigatórios. O importante é comunicar limitações e reduzir interrupções sob seu controle."},{"title":"Registre o próximo passo","text":"Ao final, confirme tarefas, responsáveis e prazos. Se a reunião for gravada, todos devem conhecer a finalidade e as regras aplicáveis antes do início; não grave por conta própria.\n\nPrática: prepare um checklist fictício com acesso, equipamento, ambiente e anotação final. Inclua como você avisaria a equipe se sua conexão caísse."}]',8,1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-digital-skills-v1-m0-l1-q0','career-course-digital-skills-v1-m0-l1','multiple_choice','Quais atitudes ajudam em uma reunião online? Selecione todas as adequadas.','Testar o acesso, controlar o microfone e confirmar os próximos passos tornam a participação mais clara. Publicar o link pode expor a reunião.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l1-q0-o0','career-course-digital-skills-v1-m0-l1-q0','Testar áudio e link antes do horário',1,0);
