INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l1-q0-o2','career-course-digital-skills-v1-m0-l1-q0','Publicar o link da reunião em um espaço aberto',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l1-q0-o3','career-course-digital-skills-v1-m0-l1-q0','Confirmar tarefas e prazos ao final',1,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-digital-skills-v1-m0-l1-q1','career-course-digital-skills-v1-m0-l1','reflection','Monte um checklist curto para uma reunião online fictícia, incluindo o que fazer se a conexão falhar.','O checklist pode incluir acesso, áudio, ambiente, materiais e um canal para avisar sobre problemas, além do registro dos próximos passos.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-digital-skills-v1-m0-l2','career-course-digital-skills-v1-m0','Comece com documentos e planilhas','[{"title":"Estruture antes de formatar","text":"Em um documento, comece pelo objetivo e organize títulos, parágrafos e listas. Use formatação para mostrar a hierarquia, não para decorar cada trecho. Em uma planilha, cada coluna deve representar um tipo de informação e cada linha, um item.\n\nEscreva títulos claros e mantenha datas e números em formatos consistentes. Uma estrutura simples facilita leitura, filtro e revisão por outras pessoas."},{"title":"Faça operações básicas com cuidado","text":"Em planilhas, pratique selecionar células, preencher linhas, ordenar, filtrar e usar uma soma simples. Antes de ordenar, confira se toda a tabela foi selecionada para não separar nomes de seus valores.\n\nFórmulas começam com um sinal próprio da ferramenta e usam referências de células. Confira alguns resultados manualmente e não apresente como certo um cálculo que você ainda não entendeu."},{"title":"Revise e compartilhe","text":"Use comentários ou sugestões quando precisar revisar sem substituir silenciosamente o trabalho de outra pessoa. Antes de compartilhar, confira permissões: visualizar, comentar ou editar. Remova dados que não sejam necessários para a tarefa.\n\nPrática: imagine uma planilha com item, responsável, prazo e situação. Explique como você organizaria as colunas e qual permissão daria a alguém que deve apenas consultar."}]',8,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-digital-skills-v1-m0-l2-q0','career-course-digital-skills-v1-m0-l2','single_choice','Uma pessoa precisa consultar uma planilha, mas não deve alterar os dados. Qual acesso é mais adequado?','A permissão de visualização atende à necessidade sem liberar edição. Permissões devem seguir a tarefa que a pessoa realmente realizará.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l2-q0-o0','career-course-digital-skills-v1-m0-l2-q0','Dar acesso de edição completa por padrão',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l2-q0-o1','career-course-digital-skills-v1-m0-l2-q0','Dar acesso de visualização e conferir o conteúdo compartilhado',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-digital-skills-v1-m0-l2-q0-o2','career-course-digital-skills-v1-m0-l2-q0','Publicar a planilha para qualquer pessoa na internet',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-digital-skills-v1-m0-l2-q1','career-course-digital-skills-v1-m0-l2','reflection','Descreva as colunas de uma planilha fictícia para acompanhar tarefas e qual permissão usaria para uma pessoa que só consulta.','Uma estrutura adequada separa item, responsável, prazo e situação. Para consulta sem alteração, a permissão de visualização costuma ser suficiente.',1);
