INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('career-course-teamwork-v1-m0','career-course-teamwork-v1','Colaboração no dia a dia',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-teamwork-v1-m0-l0','career-course-teamwork-v1-m0','Entenda papéis e combinados','[{"title":"Enxergue o resultado compartilhado","text":"Uma equipe reúne contribuições diferentes para entregar um resultado. Antes de começar, entenda o objetivo, as partes da tarefa, quem decide, quem executa e como o grupo saberá que terminou.\n\nColaborar não significa que todos façam tudo. Papéis claros evitam atividades duplicadas e tarefas esquecidas, além de facilitar o pedido de ajuda quando surgir uma dependência."},{"title":"Confirme sua responsabilidade","text":"Resuma o que ficou com você, o formato da entrega e o prazo. Pergunte quais informações ou materiais precisam chegar antes. Se o combinado mudar, atualize seu registro em vez de confiar apenas na memória.\n\nNão assuma uma tarefa de outra pessoa sem alinhar. A intenção de ajudar pode criar confusão se ninguém souber quem está responsável pelo resultado final."},{"title":"Combine como acompanhar","text":"Defina onde a equipe registrará andamento e decisões: quadro de tarefas, planilha, sistema ou mensagem no canal combinado. A atualização deve ser curta e útil, sem transformar cada pequeno passo em uma reunião.\n\nPrática: para uma atividade fictícia, escreva objetivo, sua responsabilidade, uma dependência e o lugar onde o andamento seria registrado."}]',8,0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-teamwork-v1-m0-l0-q0','career-course-teamwork-v1-m0-l0','single_choice','Duas pessoas começaram a mesma tarefa porque o responsável não foi definido. O que ajuda a evitar a repetição?','Definir responsável, resultado e local de acompanhamento torna o trabalho visível. Presumir que todos entenderam pode manter a confusão.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l0-q0-o0','career-course-teamwork-v1-m0-l0-q0','Esperar que cada pessoa descubra sozinha o que fazer',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l0-q0-o1','career-course-teamwork-v1-m0-l0-q0','Confirmar responsáveis, entrega e local de acompanhamento',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l0-q0-o2','career-course-teamwork-v1-m0-l0-q0','Parar de registrar tarefas para economizar tempo',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-teamwork-v1-m0-l0-q1','career-course-teamwork-v1-m0-l0','reflection','Defina objetivo, responsabilidade, dependência e forma de acompanhamento para uma tarefa fictícia em equipe.','A resposta deve mostrar quem faz o quê, qual resultado é esperado e onde o andamento será visível para o grupo.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-teamwork-v1-m0-l1','career-course-teamwork-v1-m0','Atualize a equipe sobre seu trabalho','[{"title":"Informe o que mudou","text":"Uma atualização útil responde: o que foi concluído, o que vem a seguir e o que está impedindo o avanço. Use fatos observáveis e indique quando precisa de uma resposta. Evite mensagens vagas como ‘estou vendo’ quando o grupo depende do resultado.\n\nA frequência depende da tarefa. Combine momentos de atualização para dar visibilidade sem interromper o trabalho a todo instante."},{"title":"Avise obstáculos cedo","text":"Se perceber que um prazo ou resultado está em risco, avise quando tiver informações suficientes para explicar a situação. Mostre o que já tentou, o que falta e qual apoio ou decisão pode destravar o trabalho.\n\nEsconder o problema até o prazo final reduz as opções da equipe. Avisar cedo não é fracasso; é uma forma de permitir que o grupo reorganize prioridades."},{"title":"Faça uma passagem clara","text":"Quando outra pessoa continuar sua tarefa, informe estado atual, arquivos, decisões, pendências e prazo. Não dependa apenas de uma conversa que não ficará registrada. Confira se a pessoa recebeu acesso ao material necessário.\n\nPrática: escreva uma atualização fictícia com concluído, próximo passo, obstáculo e pedido específico. Depois, retire qualquer detalhe que não ajude a equipe a agir."}]',8,1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-teamwork-v1-m0-l1-q0','career-course-teamwork-v1-m0-l1','multiple_choice','O que deve aparecer em uma atualização útil para a equipe? Selecione todas as adequadas.','Andamento, próximo passo e obstáculo com pedido claro ajudam o grupo a decidir. Esconder o risco ou usar uma resposta vaga não oferece informação para agir.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l1-q0-o0','career-course-teamwork-v1-m0-l1-q0','O que já foi concluído',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l1-q0-o1','career-course-teamwork-v1-m0-l1-q0','O próximo passo e o prazo relevante',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l1-q0-o2','career-course-teamwork-v1-m0-l1-q0','Um obstáculo e o apoio necessário',1,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l1-q0-o3','career-course-teamwork-v1-m0-l1-q0','Apenas a frase ‘estou vendo’ quando há um bloqueio',0,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-teamwork-v1-m0-l1-q1','career-course-teamwork-v1-m0-l1','reflection','Escreva uma atualização fictícia com andamento, próximo passo, obstáculo e um pedido específico à equipe.','A mensagem deve permitir que o grupo entenda a situação e responda ao pedido sem precisar adivinhar o que está faltando.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-teamwork-v1-m0-l2','career-course-teamwork-v1-m0','Resolva diferenças com respeito','[{"title":"Separe fato de interpretação","text":"Descreva primeiro o que aconteceu de forma observável. ‘A lista chegou depois do horário combinado’ é mais verificável do que ‘ninguém respeita meu trabalho’. Depois explique o impacto na tarefa e escute a perspectiva da outra pessoa.\n\nUma diferença pode vir de informação incompleta, prioridades distintas ou um combinado pouco claro. Verifique antes de atribuir intenção."},{"title":"Procure um próximo acordo","text":"Concentre a conversa no que precisa mudar: formato, prazo, responsável ou canal. Proponha uma ação concreta e confirme como o grupo acompanhará. Reconhecer sua parte no problema pode ajudar sem exigir que você aceite tratamento desrespeitoso.\n\nQuando a conversa ficar agressiva, discriminatória ou insegura, interrompa e procure o canal de apoio adequado da organização."},{"title":"Registre a decisão necessária","text":"Depois da conversa, registre apenas o combinado profissional relevante, evitando comentários pessoais. Se o problema se repetir, use fatos, datas e impactos para pedir apoio, respeitando as políticas da organização.\n\nPrática: transforme uma acusação genérica em uma mensagem fictícia com fato, impacto e proposta de próximo passo."}]',8,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-teamwork-v1-m0-l2-q0','career-course-teamwork-v1-m0-l2','single_choice','Uma entrega chegou depois do horário combinado e afetou a próxima tarefa. Como iniciar a conversa?','Descrever o fato e o impacto abre espaço para entender o que ocorreu e combinar uma mudança. Acusações sobre intenção aumentam o conflito sem esclarecer a tarefa.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l2-q0-o0','career-course-teamwork-v1-m0-l2-q0','Dizer que a pessoa nunca respeita ninguém',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l2-q0-o1','career-course-teamwork-v1-m0-l2-q0','Descrever o atraso, explicar o impacto e perguntar o que ocorreu',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-teamwork-v1-m0-l2-q0-o2','career-course-teamwork-v1-m0-l2-q0','Espalhar a reclamação para colegas que não participam da tarefa',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-teamwork-v1-m0-l2-q1','career-course-teamwork-v1-m0-l2','reflection','Reescreva uma reclamação fictícia usando fato, impacto e uma proposta de próximo passo, sem nomes reais.','Use algo observável, explique como a tarefa foi afetada e proponha um acordo que possa ser acompanhado pelo grupo.',1);
INSERT OR IGNORE INTO courses (id,slug,title,description,status,published_at,created_at,updated_at) VALUES ('career-course-first-days','primeiros-dias-no-trabalho','Seus primeiros dias no trabalho','Conheça a nova rotina, faça perguntas úteis e organize um plano realista para aprender durante os primeiros 30 dias.','published','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
INSERT OR IGNORE INTO course_versions (id,course_id,version,status,pass_score,created_at,published_at) VALUES ('career-course-first-days-v1','career-course-first-days',1,'published',70,'2026-09-24T00:00:00.000Z','2026-09-24T00:00:00.000Z');
INSERT OR IGNORE INTO course_modules (id,course_version_id,title,position) VALUES ('career-course-first-days-v1-m0','career-course-first-days-v1','Comece uma nova rotina com clareza',0);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-first-days-v1-m0-l0','career-course-first-days-v1-m0','Observe a rotina e as regras','[{"title":"Conheça o funcionamento básico","text":"Nos primeiros dias, identifique horários, local ou acesso, pessoas de referência, pausas, registro de presença e canais de comunicação. Pergunte onde encontrar orientações oficiais em vez de depender apenas de comentários informais.\n\nAnote o necessário sem registrar senhas ou informações confidenciais. Cada organização possui práticas próprias, e você não precisa memorizar tudo de uma vez."},{"title":"Entenda prioridades e qualidade","text":"Para cada atividade inicial, confirme o resultado esperado, a prioridade, o prazo e como o trabalho será conferido. Observe exemplos aprovados quando estiverem disponíveis e pergunte quais erros são mais importantes evitar.\n\nRapidez não é o único sinal de bom trabalho. No começo, compreender o processo e realizar uma entrega correta pode ser mais valioso do que tentar parecer independente a qualquer custo."},{"title":"Respeite segurança e confidencialidade","text":"Siga orientações sobre equipamentos, dados de clientes, acesso a sistemas e segurança física. Não compartilhe credenciais nem copie informações de trabalho para contas pessoais sem autorização.\n\nSe uma instrução parecer insegura ou contrariar uma regra conhecida, pare e confirme com a pessoa ou canal responsável. Prática: faça uma lista fictícia com cinco informações que você buscaria no primeiro dia."}]',8,0);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-first-days-v1-m0-l0-q0','career-course-first-days-v1-m0-l0','multiple_choice','Quais informações ajudam no primeiro dia? Selecione todas as adequadas.','Pessoas de referência, prioridades e regras de acesso ajudam a trabalhar com segurança. Compartilhar senha não é uma forma adequada de integração.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l0-q0-o0','career-course-first-days-v1-m0-l0-q0','Quem pode orientar quando surgir uma dúvida',1,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l0-q0-o1','career-course-first-days-v1-m0-l0-q0','Quais tarefas são prioridade e como serão conferidas',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l0-q0-o2','career-course-first-days-v1-m0-l0-q0','Qual senha de outra pessoa posso usar',0,2);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l0-q0-o3','career-course-first-days-v1-m0-l0-q0','Onde ficam as regras e canais oficiais',1,3);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-first-days-v1-m0-l0-q1','career-course-first-days-v1-m0-l0','reflection','Liste cinco informações que você gostaria de confirmar no primeiro dia de uma situação fictícia de trabalho.','Considere rotina, prioridade, pessoas de referência, segurança e canais oficiais. Não inclua nomes, endereços ou credenciais reais.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-first-days-v1-m0-l1','career-course-first-days-v1-m0','Faça perguntas que ajudam a aprender','[{"title":"Mostre o que você já entendeu","text":"Antes de perguntar, organize a dúvida: qual é a tarefa, o que você entendeu e qual ponto impede o próximo passo. Uma pergunta específica facilita a resposta e mostra que você acompanhou a orientação.\n\nExemplo: ‘Entendi que devo separar os pedidos de hoje por prioridade. Como identifico os casos urgentes?’ é mais útil do que apenas dizer ‘não entendi nada’."},{"title":"Escolha momento e canal","text":"Dúvidas que envolvem risco, cliente esperando ou bloqueio de trabalho devem ser comunicadas logo. Outras podem ser reunidas para o momento combinado de acompanhamento. Use o canal definido pela equipe e respeite situações em que a pessoa não pode responder imediatamente.\n\nAnote a resposta com suas próprias palavras e confirme se o entendimento está correto. Isso reduz a necessidade de repetir a mesma pergunta."},{"title":"Aprenda sem esconder limites","text":"Dizer que ainda não sabe usar uma ferramenta é mais seguro do que fingir domínio e causar um problema. Relacione o que já conhece, peça uma demonstração ou material e combine como praticará.\n\nPrática: transforme uma dúvida vaga em uma pergunta que contenha contexto, entendimento atual e o ponto exato a esclarecer."}]',8,1);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-first-days-v1-m0-l1-q0','career-course-first-days-v1-m0-l1','single_choice','Você entendeu a tarefa, mas não sabe identificar quais pedidos são urgentes. Qual pergunta é mais útil?','Informar o que você já entendeu e localizar a dúvida permite uma resposta específica. Fingir que sabe pode gerar erros evitáveis.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l1-q0-o0','career-course-first-days-v1-m0-l1-q0','Não perguntar e escolher qualquer pedido como urgente',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l1-q0-o1','career-course-first-days-v1-m0-l1-q0','Entendi a separação por prioridade; qual critério identifica um pedido urgente?',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l1-q0-o2','career-course-first-days-v1-m0-l1-q0','Dizer apenas que tudo está confuso, sem citar a tarefa',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-first-days-v1-m0-l1-q1','career-course-first-days-v1-m0-l1','reflection','Transforme uma dúvida vaga sobre uma tarefa fictícia em uma pergunta com contexto, entendimento atual e ponto a esclarecer.','A pergunta deve mostrar o que já está claro e permitir que a outra pessoa responda ao ponto que bloqueia o próximo passo.',1);
INSERT OR IGNORE INTO lessons (id,module_id,title,content_json,estimated_minutes,position) VALUES ('career-course-first-days-v1-m0-l2','career-course-first-days-v1-m0','Organize seus primeiros 30 dias','[{"title":"Defina aprendizados possíveis","text":"Escolha poucos objetivos ligados à função: compreender uma rotina, usar uma ferramenta básica ou realizar uma tarefa com acompanhamento. Um objetivo deve depender principalmente das suas ações e ter uma forma simples de verificar avanço.\n\nEvite a meta de ‘não cometer nenhum erro’. Prefira algo como ‘seguir o checklist e pedir conferência nas três primeiras entregas’."},{"title":"Registre progresso e dúvidas","text":"Ao fim de cada semana, anote o que conseguiu realizar, quais orientações recebeu e o que ainda precisa praticar. Use exemplos de trabalho sem copiar dados confidenciais. Leve dúvidas prioritárias para o acompanhamento combinado.\n\nPequenos registros ajudam a perceber evolução e preparar conversas de feedback. Eles não precisam ser longos nem conter julgamento sobre colegas."},{"title":"Revise com a pessoa responsável","text":"Quando houver espaço, confirme se suas prioridades estão alinhadas e peça um exemplo concreto de algo que pode melhorar. Resuma a ação que fará e combine quando verificar novamente.\n\nO plano precisa se adaptar à rotina real e às orientações da organização. Prática: monte um plano fictício de 30 dias com dois aprendizados, uma forma de praticar e um momento de revisão."}]',8,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-first-days-v1-m0-l2-q0','career-course-first-days-v1-m0-l2','single_choice','Qual objetivo é mais útil para os primeiros 30 dias?','Um objetivo específico e verificável orienta a prática. Exigir perfeição imediata não mostra qual ação realizar nem considera o período de aprendizagem.',0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l2-q0-o0','career-course-first-days-v1-m0-l2-q0','Nunca cometer nenhum erro desde o primeiro dia',0,0);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l2-q0-o1','career-course-first-days-v1-m0-l2-q0','Usar o checklist e pedir revisão nas primeiras entregas',1,1);
INSERT OR IGNORE INTO quiz_options (id,question_id,label,is_correct,position) VALUES ('career-course-first-days-v1-m0-l2-q0-o2','career-course-first-days-v1-m0-l2-q0','Aprender todas as funções da organização em uma semana',0,2);
INSERT OR IGNORE INTO quiz_questions (id,lesson_id,type,prompt,explanation,position) VALUES ('career-course-first-days-v1-m0-l2-q1','career-course-first-days-v1-m0-l2','reflection','Crie um plano fictício de 30 dias com dois aprendizados, uma prática e um momento de revisão.','Prefira metas pequenas, relacionadas à função e verificáveis. Inclua como você praticará e quando pedirá orientação sobre o avanço.',1);
